func openFile(name string) (*os.File, func()) {
	file, err := os.OpenFile(name, os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		panic(err)
	}
	closer := func() {
		err := file.Close()
		if err != nil {
			fmt.Println("Error closing file:", err)议
		}
	}
	return file, closer
}

func writeToFile(file *os.File, data string) {
	_, err := file.WriteString(data)
	if err != nil {
		panic(err)
	}
}

import Foundation

func processUserInput(userInput: String) -> String? {
    guard let escapedUserInput = userInput.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
          let sanitizedUserInput = String(describing: escapedUserInput) else {
        return nil
    }

    let task = Process()
    task.launchPath = "/bin/sh"
    task.arguments = ["-c", sanitizedUserInput]

    let outputPipe = Pipe()
    task.standardOutput = outputPipe
    task.standardError = outputPipe

    task.launch()

    let data = outputPipe.fileHandleForReading.readDataToEndOfFile()
    if let output = String(data: data, encoding: .utf8) {
        return output
    } else {
        return nil
    }
}

