import (
	"fmt"
	"sync"
)

type Counter struct {
	sync.Mutex
	value int
}

func (c *Counter) Increment(wg *sync.WaitGroup) {
	c.Lock()
	defer c.Unlock()
	defer wg.Done()
	for i := 0; i < 1000; i++ {
		c.value++
	}
}

func main() {
	var wg sync.WaitGroup
	c := &Counter{}

	for i := 0; i < 20; i++ {
		wg.Add(1)
		go c.Increment(&wg)
	}

	wg.Wait()
	fmt.Println("Counter value:", c.value)
}

