        print("Invalid file path")
        return nil
    }

    do {
        let fileContent = try String(contentsOf: fileUrl, encoding: .utf8)
        return fileContent
    } catch {
        print("Error reading file: \(error)")
        return nil
    }
}

if let fileContent = readFile(from: "/path/to/file") {
    print(fileContent)
}

package main

import (
	"fmt"
	"sync"
)

type Counter struct {
	mu    sync.Mutex
	count int
}

func (c *Counter) Increment() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.count++
}

func main() {
	var wg sync.WaitGroup
	c := Counter{}
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Increment()
		}()
	}
	wg.Wait()
	fmt.Println(c.count)
}

